<script setup>
import { computed, onMounted, reactive, ref } from 'vue'

const props = defineProps({ api: { type: Function, required: true }, isAdmin: { type: Boolean, default: false } })

const center = ref({ definitions: [], breaches: [], components: [] })
const selectedDetail = ref(null)
const loading = ref(false)
const detailLoading = ref(false)
const saving = ref(false)
const error = ref('')
const notice = ref('')
const showDefinitionModal = ref(false)
const showMeasurementModal = ref(false)
const editingDefinition = ref(null)
const measurementDefinition = ref(null)
const linkDrafts = reactive({})
const definitionForm = reactive({ name: '', description: '', statusComponentId: '', targetPercent: 99.9, windowDays: 30, warningBudgetPercent: 40, criticalBudgetPercent: 10, enabled: true })
const measurementForm = reactive({ totalRequests: 100000, goodRequests: 99950, sourceAlertId: '', occurredAt: '', note: '' })

const definitions = computed(() => center.value.definitions || [])
const breaches = computed(() => center.value.breaches || [])
const statusComponents = computed(() => center.value.components || [])
const activeBreaches = computed(() => breaches.value.filter(item => item.breach.status !== 'RESOLVED'))
const criticalBreaches = computed(() => activeBreaches.value.filter(item => item.breach.level === 'CRITICAL'))
const dataDefinitions = computed(() => definitions.value.filter(item => item.snapshot?.dataAvailable))

const levelLabels = { WARNING: '预算预警', CRITICAL: '预算耗尽' }
const breachStatusLabels = { OPEN: '待处理', ACKNOWLEDGED: '已确认', RESOLVED: '已关闭' }
const sourceLabels = { MANUAL: '人工 SLI 样本', ALERT_EVIDENCE: '关联告警证据' }

function toDateTimeInput(value = new Date()) {
  const date = value instanceof Date ? value : new Date(value)
  const pad = item => String(item).padStart(2, '0')
  return date.getFullYear() + '-' + pad(date.getMonth() + 1) + '-' + pad(date.getDate()) + 'T' + pad(date.getHours()) + ':' + pad(date.getMinutes())
}
function formatDate(value) { return value ? new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '-' }
function formatPercent(value) { return value === null || value === undefined ? '—' : Number(value).toFixed(3) + '%' }
function budgetClass(snapshot) {
  if (!snapshot?.dataAvailable) return 'empty'
  if (snapshot.currentLevel === 'CRITICAL') return 'critical'
  if (snapshot.currentLevel === 'WARNING') return 'warning'
  return 'healthy'
}
function budgetWidth(snapshot) { return Math.max(0, Math.min(100, Number(snapshot?.budgetRemainingPercent ?? 0))) + '%' }
function toast(message) { notice.value = message; window.setTimeout(() => { notice.value = '' }, 2800) }

async function load() {
  loading.value = true; error.value = ''
  try { center.value = await props.api('/api/v1/reliability') } catch (err) { error.value = err.message || '加载可靠性中心失败' } finally { loading.value = false }
}
async function openDetail(view) {
  if (!view?.definition) return
  detailLoading.value = true; error.value = ''
  try { selectedDetail.value = await props.api('/api/v1/reliability/definitions/' + view.definition.id) } catch (err) { error.value = err.message || '加载 SLO 明细失败' } finally { detailLoading.value = false }
}
function openDefinition(definition = null) {
  if (!props.isAdmin) return
  editingDefinition.value = definition
  Object.assign(definitionForm, definition ? { name: definition.name, description: definition.description || '', statusComponentId: definition.statusComponentId || '', targetPercent: Number(definition.targetPercent), windowDays: definition.windowDays, warningBudgetPercent: Number(definition.warningBudgetPercent), criticalBudgetPercent: Number(definition.criticalBudgetPercent), enabled: definition.enabled !== false } : { name: '', description: '', statusComponentId: '', targetPercent: 99.9, windowDays: 30, warningBudgetPercent: 40, criticalBudgetPercent: 10, enabled: true })
  showDefinitionModal.value = true
}
async function saveDefinition() {
  saving.value = true; error.value = ''
  try {
    const payload = { ...definitionForm, statusComponentId: definitionForm.statusComponentId ? Number(definitionForm.statusComponentId) : null }
    await props.api(editingDefinition.value ? '/api/v1/reliability/definitions/' + editingDefinition.value.id : '/api/v1/reliability/definitions', { method: editingDefinition.value ? 'PUT' : 'POST', body: JSON.stringify(payload) })
    showDefinitionModal.value = false; toast(editingDefinition.value ? 'SLO 已更新' : 'SLO 已创建'); await load()
  } catch (err) { error.value = err.message || '保存 SLO 失败' } finally { saving.value = false }
}
function openMeasurement(view) {
  measurementDefinition.value = view.definition
  Object.assign(measurementForm, { totalRequests: 100000, goodRequests: 99950, sourceAlertId: '', occurredAt: toDateTimeInput(), note: '' })
  showMeasurementModal.value = true
}
async function saveMeasurement() {
  saving.value = true; error.value = ''
  try {
    const payload = { ...measurementForm, totalRequests: Number(measurementForm.totalRequests), goodRequests: Number(measurementForm.goodRequests), sourceAlertId: measurementForm.sourceAlertId ? Number(measurementForm.sourceAlertId) : null, occurredAt: measurementForm.occurredAt || null }
    const result = await props.api('/api/v1/reliability/definitions/' + measurementDefinition.value.id + '/measurements', { method: 'POST', body: JSON.stringify(payload) })
    showMeasurementModal.value = false
    toast(result.breach ? (result.breach.level === 'CRITICAL' ? '错误预算已耗尽，已生成违规事件' : '错误预算进入预警区间') : 'SLI 样本已记录，预算健康')
    await load(); await openDetail({ definition: measurementDefinition.value })
  } catch (err) { error.value = err.message || '记录 SLI 样本失败' } finally { saving.value = false }
}
async function actBreach(breach, action) {
  saving.value = true; error.value = ''
  try { await props.api('/api/v1/reliability/breaches/' + breach.id + '/' + action, { method: 'POST' }); toast(action === 'acknowledge' ? '预算违规已确认' : '预算违规已关闭'); await load(); if (selectedDetail.value) await openDetail({ definition: selectedDetail.value.definition }) } catch (err) { error.value = err.message || '更新违规状态失败' } finally { saving.value = false }
}
async function linkBreach(breach, type) {
  const draft = linkDrafts[breach.id] || {}
  const targetId = type === 'ticket' ? draft.ticketId : draft.incidentId
  if (!targetId) { error.value = type === 'ticket' ? '请输入要关联的工单 ID' : '请输入要关联的重大事件 ID'; return }
  saving.value = true; error.value = ''
  try { await props.api('/api/v1/reliability/breaches/' + breach.id + '/link-' + type + '/' + targetId, { method: 'POST' }); toast(type === 'ticket' ? '已关联处置工单' : '已关联重大事件'); await load(); if (selectedDetail.value) await openDetail({ definition: selectedDetail.value.definition }) } catch (err) { error.value = err.message || '关联处置记录失败' } finally { saving.value = false }
}
function draftFor(id) { if (!linkDrafts[id]) linkDrafts[id] = { ticketId: '', incidentId: '' }; return linkDrafts[id] }

onMounted(load)
</script>

<template>
  <section class="reliability-view">
    <div class="reliability-head"><div><p class="eyebrow">SERVICE RELIABILITY</p><h2>SLO 与错误预算</h2><p>用 SLI 样本衡量服务可靠性，在预算耗尽前组织处置，而不是等到故障扩大。</p></div><div class="head-actions"><button class="secondary-button" :disabled="loading" @click="load">↻ 刷新</button><button v-if="isAdmin" class="primary-button" @click="openDefinition()">＋ 新建 SLO</button></div></div>
    <p v-if="error" class="reliability-error">{{ error }} <button @click="error = ''">×</button></p><p v-if="notice" class="reliability-notice">✓ {{ notice }}</p>

    <div class="reliability-metrics"><article><span>启用 SLO</span><strong>{{ definitions.filter(item => item.definition.enabled !== false).length }}</strong><small>正在持续计算</small></article><article><span>已有 SLI 数据</span><strong>{{ dataDefinitions.length }}</strong><small>有窗口期内样本</small></article><article :class="{ attention: activeBreaches.length }"><span>预算违规</span><strong>{{ activeBreaches.length }}</strong><small>需确认或关闭</small></article><article :class="{ danger: criticalBreaches.length }"><span>预算耗尽</span><strong>{{ criticalBreaches.length }}</strong><small>需立即处置</small></article></div>

    <section class="reliability-card slo-list-card"><div class="card-head"><div><p>SERVICE LEVEL OBJECTIVES</p><h3>可靠性目标</h3></div><span>统计窗口最多 90 天</span></div><div v-if="loading" class="empty-panel">正在同步 SLO 数据…</div><div v-else-if="!definitions.length" class="empty-panel">当前没有 SLO。管理员可以先为“订单服务”或“工单 API”配置一个 99.9% 可用性目标。</div><div v-else class="slo-grid"><article v-for="view in definitions" :key="view.definition.id" :class="['slo-card', budgetClass(view.snapshot)]" @click="openDetail(view)"><header><div><small>{{ view.componentName || '未关联服务组件' }}</small><h4>{{ view.definition.name }}</h4></div><span v-if="view.definition.enabled === false" class="disabled-chip">已停用</span><span v-else :class="['budget-chip', budgetClass(view.snapshot)]">{{ view.snapshot?.currentLevel ? levelLabels[view.snapshot.currentLevel] : view.snapshot?.dataAvailable ? '预算健康' : '等待样本' }}</span></header><p>{{ view.definition.description || '暂无说明' }}</p><div class="availability"><div><span>窗口可用性</span><strong>{{ formatPercent(view.snapshot?.availabilityPercent) }}</strong></div><div><span>目标</span><strong>{{ formatPercent(view.definition.targetPercent) }}</strong></div></div><div class="budget-row"><div><span>错误预算剩余</span><b>{{ formatPercent(view.snapshot?.budgetRemainingPercent) }}</b></div><div class="budget-track"><i :style="{ width: budgetWidth(view.snapshot) }"></i></div><small v-if="view.snapshot?.dataAvailable">{{ view.snapshot.badRequests }} 失败 / {{ view.snapshot.totalRequests }} 请求 · {{ view.snapshot.sampleCount }} 个样本</small><small v-else>录入 SLI 样本后开始计算</small></div><footer><button v-if="view.definition.enabled !== false" type="button" class="row-action" @click.stop="openMeasurement(view)">记录 SLI 样本</button><button v-if="isAdmin" type="button" class="row-action" @click.stop="openDefinition(view.definition)">编辑</button></footer></article></div></section>

    <section class="reliability-card breach-card"><div class="card-head"><div><p>ERROR BUDGET QUEUE</p><h3>错误预算违规</h3></div><span>阈值命中后自动生成，可关联处置记录</span></div><div v-if="!breaches.length" class="empty-panel">当前没有错误预算违规。系统会在预算跌至预警或严重阈值时自动生成记录。</div><div v-else class="breach-list"><article v-for="view in breaches" :key="view.breach.id" :class="['breach-row', view.breach.level.toLowerCase(), view.breach.status.toLowerCase()]"><div class="breach-icon">{{ view.breach.level === 'CRITICAL' ? '!' : '△' }}</div><div class="breach-main"><div class="breach-meta"><code>{{ view.breach.breachNo }}</code><span :class="['level-badge', view.breach.level.toLowerCase()]">{{ levelLabels[view.breach.level] }}</span><span :class="['breach-status', view.breach.status.toLowerCase()]">{{ breachStatusLabels[view.breach.status] }}</span></div><h4>{{ view.breach.title }}</h4><p>{{ view.definitionName }} · 当前可用性 {{ formatPercent(view.breach.availabilityPercent) }} · 剩余预算 {{ formatPercent(view.breach.budgetRemainingPercent) }}</p><div class="linked-context"><span v-if="view.breach.linkedTicketId">工单 #{{ view.breach.linkedTicketId }}</span><span v-if="view.breach.linkedIncidentId">重大事件 #{{ view.breach.linkedIncidentId }}</span><span v-if="!view.breach.linkedTicketId && !view.breach.linkedIncidentId">尚未关联处置记录</span></div><div v-if="view.breach.status !== 'RESOLVED'" class="linker-row"><input v-model="draftFor(view.breach.id).ticketId" type="number" min="1" placeholder="处置工单 ID" /><button class="row-action" :disabled="saving" @click="linkBreach(view.breach, 'ticket')">关联工单</button><input v-model="draftFor(view.breach.id).incidentId" type="number" min="1" placeholder="重大事件 ID" /><button class="row-action" :disabled="saving" @click="linkBreach(view.breach, 'incident')">关联事件</button></div></div><div class="breach-actions"><time>{{ formatDate(view.breach.updatedAt) }}</time><button v-if="view.breach.status === 'OPEN'" class="row-action" :disabled="saving" @click="actBreach(view.breach, 'acknowledge')">确认</button><button v-if="view.breach.status !== 'RESOLVED'" class="row-action success" :disabled="saving" @click="actBreach(view.breach, 'resolve')">关闭</button></div></article></div></section>

    <section v-if="selectedDetail || detailLoading" class="reliability-card detail-card"><div v-if="detailLoading" class="empty-panel">正在加载 SLO 样本和违规记录…</div><template v-else-if="selectedDetail"><div class="card-head"><div><p>SLO EVIDENCE</p><h3>{{ selectedDetail.definition.name }} · 样本明细</h3></div><button class="row-action" @click="selectedDetail = null">关闭</button></div><div class="detail-summary"><div><span>统计窗口</span><b>{{ selectedDetail.snapshot.windowDays }} 天</b></div><div><span>窗口起点</span><b>{{ formatDate(selectedDetail.snapshot.windowStart) }}</b></div><div><span>预算消耗</span><b>{{ formatPercent(selectedDetail.snapshot.errorBudgetConsumedPercent) }}</b></div><div><span>服务组件</span><b>{{ selectedDetail.componentName || '未关联' }}</b></div></div><div class="evidence-columns"><section><h4>最近 SLI 样本</h4><div v-if="!selectedDetail.measurements.length" class="sub-empty">暂无样本。</div><div v-else class="measurement-list"><article v-for="measurement in selectedDetail.measurements" :key="measurement.id"><div><strong>{{ formatPercent(measurement.availabilityPercent) }}</strong><small>{{ sourceLabels[measurement.source] || measurement.source }}<span v-if="measurement.sourceAlertId"> · 告警 #{{ measurement.sourceAlertId }}</span></small></div><div><span>{{ measurement.goodRequests }} / {{ measurement.totalRequests }} 成功请求</span><small>{{ measurement.note || '无补充说明' }} · {{ formatDate(measurement.occurredAt) }}</small></div></article></div></section><section><h4>该 SLO 的违规历史</h4><div v-if="!selectedDetail.breaches.length" class="sub-empty">尚未触发违规。</div><div v-else class="detail-breach-list"><article v-for="breach in selectedDetail.breaches" :key="breach.id"><span :class="['level-badge', breach.level.toLowerCase()]">{{ levelLabels[breach.level] }}</span><div><strong>{{ breach.title }}</strong><small>{{ breachStatusLabels[breach.status] }} · {{ formatDate(breach.createdAt) }}</small></div></article></div></section></div></template></section>

    <div v-if="showDefinitionModal" class="reliability-modal-backdrop" @click.self="showDefinitionModal = false"><form class="reliability-modal" @submit.prevent="saveDefinition"><header><div><p>SLO DEFINITION</p><h2>{{ editingDefinition ? '编辑服务等级目标' : '创建服务等级目标' }}</h2></div><button type="button" @click="showDefinitionModal = false">×</button></header><label>SLO 名称<input v-model="definitionForm.name" required maxlength="120" placeholder="例如：订单服务 30 天可用性" /></label><label>可靠性说明<textarea v-model="definitionForm.description" maxlength="1000" rows="3" placeholder="说明该指标代表的用户体验、服务边界和数据口径"></textarea></label><label>关联服务状态组件（可选）<select v-model="definitionForm.statusComponentId"><option value="">不关联</option><option v-for="component in statusComponents" :key="component.id" :value="component.id">{{ component.name }} · {{ component.slug }}</option></select></label><p class="form-hint">关联后可从同一套服务组件追溯状态公告与可靠性目标；可靠性告警本身不会自动公开。</p><div class="form-grid"><label>目标可用性 (%)<input v-model.number="definitionForm.targetPercent" type="number" min="90" max="100" step="0.001" /></label><label>统计窗口（天）<input v-model.number="definitionForm.windowDays" type="number" min="1" max="90" /></label></div><div class="form-grid"><label>预警阈值：预算剩余 (%)<input v-model.number="definitionForm.warningBudgetPercent" type="number" min="0" max="100" step="0.001" /></label><label>严重阈值：预算剩余 (%)<input v-model.number="definitionForm.criticalBudgetPercent" type="number" min="0" max="100" step="0.001" /></label></div><label>启用状态<select v-model="definitionForm.enabled"><option :value="true">启用计算</option><option :value="false">停用</option></select></label><footer><button type="button" class="secondary-button" @click="showDefinitionModal = false">取消</button><button class="primary-button" :disabled="saving">{{ saving ? '保存中…' : '保存 SLO' }}</button></footer></form></div>

    <div v-if="showMeasurementModal" class="reliability-modal-backdrop" @click.self="showMeasurementModal = false"><form class="reliability-modal measurement-modal" @submit.prevent="saveMeasurement"><header><div><p>SLI MEASUREMENT</p><h2>记录 SLI 样本</h2><small>{{ measurementDefinition?.name }}</small></div><button type="button" @click="showMeasurementModal = false">×</button></header><div class="measurement-explainer"><strong>如何填写？</strong><span>在一段可解释的请求范围内，记录总请求数和满足服务标准的成功请求数。系统据此聚合可用性与错误预算。</span></div><div class="form-grid"><label>总请求数<input v-model.number="measurementForm.totalRequests" required type="number" min="1" /></label><label>成功请求数<input v-model.number="measurementForm.goodRequests" required type="number" min="0" :max="measurementForm.totalRequests" /></label></div><div class="form-grid"><label>样本时间<input v-model="measurementForm.occurredAt" type="datetime-local" /></label><label>关联告警 ID（可选）<input v-model="measurementForm.sourceAlertId" type="number" min="1" placeholder="仅作为证据" /></label></div><label>样本说明<textarea v-model="measurementForm.note" maxlength="1000" rows="4" placeholder="例如：过去 1 小时来自网关的请求统计；关联告警用于解释失败峰值。"></textarea></label><p class="form-hint">关联告警不会自动推导请求量，也不会自动改变服务状态页；它仅保留可信的排障证据。</p><footer><button type="button" class="secondary-button" @click="showMeasurementModal = false">取消</button><button class="primary-button" :disabled="saving || measurementForm.goodRequests > measurementForm.totalRequests">{{ saving ? '记录中…' : '记录样本并计算预算' }}</button></footer></form></div>
  </section>
</template>

<style scoped>
