 18px; }.card-head { display: flex; justify-content: space-between; gap: 12px; align-items: flex-start; }.card-head h3 { margin: 5px 0 0; font-size: 16px; }.card-head > span { color: #8290a4; font-size: 12px; }.empty-panel, .sub-empty { border: 1px dashed #dae2ec; border-radius: 8px; padding: 30px 16px; color: #8491a4; text-align: center; font-size: 13px; margin-top: 16px; }.slo-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 13px; margin-top: 17px; }.slo-card { cursor: pointer; padding: 16px; border: 1px solid #e3e9f1; border-top: 3px solid #51a878; border-radius: 9px; background: #fff; transition: transform .14s, box-shadow .14s; }.slo-card:hover { transform: translateY(-2px); box-shadow: 0 8px 18px rgba(26, 49, 78, .08); }.slo-card.warning { border-top-color: #d59a2b; }.slo-card.critical { border-top-color: #c84c57; }.slo-card.empty { border-top-color: #aab6c5; }.slo-card header { display: flex; justify-content: space-between; gap: 10px; }.slo-card header small { color: #718197; font-size: 11px; }.slo-card h4 { margin: 4px 0 0; font-size: 15px; }.disabled-chip, .budget-chip, .level-badge, .breach-status { padding: 4px 7px; border-radius: 999px; font-size: 10px; font-weight: 800; white-space: nowrap; }.disabled-chip { background: #f0f2f5; color: #7e8998; }.budget-chip.healthy { background: #eaf7f0; color: #167650; }.budget-chip.warning { background: #fff4df; color: #a26209; }.budget-chip.critical { background: #fff0f1; color: #b63f4b; }.budget-chip.empty { background: #f1f4f7; color: #768399; }.slo-card > p { min-height: 38px; margin: 12px 0; color: #728096; font-size: 12px; line-height: 1.55; }.availability { display: grid; grid-template-columns: 1fr 1fr; padding: 11px 0; border-top: 1px solid #edf1f4; border-bottom: 1px solid #edf1f4; }.availability > div + div { padding-left: 12px; border-left: 1px solid #edf1f4; }.availability span, .budget-row span { display: block; color: #8090a3; font-size: 10px; }.availability strong { margin-top: 3px; di